sys_script_include.script:
var UserLookup = Class.create();
UserLookup.prototype = {
    initialize: function() {},

    getUserDetails: function(userId) {
        if (!userId) {
            return {
                success: false,
                message: "User ID is required"
            };
        }

        // Query sys_user table to get user details
        var userGr = new GlideRecord('sys_user');
        userGr.addQuery('sys_id', userId);
        userGr.setLimit(1);
        userGr.query();

        if (userGr.next()) {
            return {
                success: true,
                firstName: userGr.getValue('first_name'),
                lastName: userGr.getValue('last_name'),
                manager: userGr.getValue('manager'),
                email: userGr.getValue('email'),
                message: "User details retrieved successfully"
            };
        } else {
            return {
                success: false,
                message: "User not found"
            };
        }
    },

    type: 'UserLookup'
};
